const msg = $('Extract Message').first().json;
const row = $input.first()?.json || {};

const phone = String(msg.phone_number || '').trim();
const text = String(msg.message || '').trim();
const messageId = String(msg.message_id || '');

if (!phone) throw new Error('Customer phone number is missing');

// Meta sometimes delivers the same webhook twice: never answer a message twice.
if (messageId && String(row.last_message_id || '') === messageId) return [];

const num = v => { if (v === '' || v === null || v === undefined) return 0; const n = Number(v); return Number.isFinite(n) ? n : 0; };
const bool = v => String(v).trim().toLowerCase() === 'true';
const hhmm = v => { const m = String(v || '').match(/^(\d{1,2}):(\d{2})/); return m ? m[1].padStart(2, '0') + ':' + m[2] : ''; };
const ymd = v => { const m = String(v || '').match(/^\d{4}-\d{2}-\d{2}/); return m ? m[0] : ''; };

// A listing ID typed in THIS message wins over the saved one.
const typedId = (text.match(/\bVUL-[A-Z0-9]{4,12}\b/i) || [])[0] || '';

const state = {
  phone,
  customer_name: row.customer_name || msg.customer_name || '',
  last_intent: row.last_intent || '',
  budget_min: num(row.budget_min),
  budget_max: num(row.budget_max),
  bhk: num(row.bhk),
  locality: row.locality || '',
  locality_flexible: bool(row.locality_flexible),
  property_type: row.property_type || '',
  furnishing: row.furnishing || '',
  possession_pref: row.possession_pref || '',
  shown_properties: row.shown_properties || '',
  selected_property_id: typedId ? typedId.toUpperCase() : (row.selected_property_id || ''),
  meeting_date: ymd(row.meeting_date),
  meeting_time: hhmm(row.meeting_time),
  booking_status: row.booking_status || '',
  history: row.history || ''
};

const state_text = [
  'customer_name: ' + (state.customer_name || 'unknown'),
  'budget_min_inr: ' + (state.budget_min || 'unknown'),
  'budget_max_inr: ' + (state.budget_max || 'unknown'),
  'bhk: ' + (state.bhk || 'unknown'),
  'locality: ' + (state.locality || 'unknown'),
  'locality_flexible: ' + state.locality_flexible,
  'property_type: ' + (state.property_type || 'unknown'),
  'furnishing: ' + (state.furnishing || 'unknown'),
  'selected_property_id: ' + (state.selected_property_id || 'none'),
  'meeting_date: ' + (state.meeting_date || 'none'),
  'meeting_time: ' + (state.meeting_time || 'none'),
  'last_intent: ' + (state.last_intent || 'none'),
  'booking_status: ' + (state.booking_status || 'none')
].join('\n');

const shown_text = String(state.shown_properties).split(';').filter(Boolean).map(x => x.split('|').join(' | ')).join('\n') || 'none';
const history_text = String(state.history).split(' ## ').filter(Boolean).join('\n') || 'none';

return [{ json: { phone, text, message_id: messageId, wa_name: state.customer_name, state, state_text, shown_text, history_text } }];

